// Deterministic evolving volumetric-looking 2D cloud fields, with temporal interpolation.
export const livingSkyDefaults={skyWind:24,skyEvolution:.16,skyDensity:.68,skyOpacity:1,skyScale:1,skyLayers:3,skySeed:37,skyColor:'#c60c24',skyCloudColor:'#140b16',skyLight:.45,skyDirection:1,skyShadowStrength:.16};
const clamp=x=>Math.max(0,Math.min(1,x)),smooth=x=>x*x*(3-2*x),mix=(a,b,q)=>a+(b-a)*q;
function hash(x,y,z,s){let n=(Math.imul(x,374761393)+Math.imul(y,668265263)+Math.imul(z,1442695041)+Math.imul(s,1597334677))|0;n=Math.imul(n^(n>>>13),1274126177);return ((n^(n>>>16))>>>0)/4294967295;}
export function skyNoise(x,y,z,seed=37){const X=Math.floor(x),Y=Math.floor(y),Z=Math.floor(z),u=smooth(x-X),v=smooth(y-Y),w=smooth(z-Z);return mix(mix(mix(hash(X,Y,Z,seed),hash(X+1,Y,Z,seed),u),mix(hash(X,Y+1,Z,seed),hash(X+1,Y+1,Z,seed),u),v),mix(mix(hash(X,Y,Z+1,seed),hash(X+1,Y,Z+1,seed),u),mix(hash(X,Y+1,Z+1,seed),hash(X+1,Y+1,Z+1,seed),u),v),w);}
function fbm(x,y,time,f){let sum=0,weight=.55,den=0;for(let i=0;i<5;i++){const scale=2**i;sum+=skyNoise(x*scale,y*scale,time*f.skyEvolution*(1+i*.12),f.skySeed+i*11)*weight;den+=weight;weight*=.52;}return sum/den;}
export function cloudField(x,y,time,input={}){return fbm(x,y,time,{...livingSkyDefaults,...input})}
const cache=new Map();function fieldFrame(frame,layer,f){const key=JSON.stringify([frame,layer,...Object.values(f)]);if(cache.has(key))return cache.get(key);const cv=Object.assign(document.createElement('canvas'),{width:256,height:128}),c=cv.getContext('2d'),im=c.createImageData(256,128),t=frame/8,seed=f.skySeed+layer*97,settings={...f,skySeed:seed},col=[1,3,5].map(i=>parseInt(f.skyCloudColor.slice(i,i+2),16));for(let y=0;y<128;y++)for(let x=0;x<256;x++){const X=x/256*(3.2+layer*.6)/f.skyScale-t*f.skyWind*f.skyDirection/960*(.5+layer*.42)*(3.2+layer*.6)/f.skyScale,Y=y/128*(1.8+layer*.4),warp=skyNoise(X*.7,Y*.7,t*f.skyEvolution*.3,seed)*.7,n=fbm(X+warp,Y,t,settings),density=clamp((n-(.76-f.skyDensity*.5))*5),wisps=clamp((n-.38)*3),a=density*wisps*clamp((1-y/150)*1.7),i=(y*256+x)*4,light=clamp((n-.5)*2)*f.skyLight;im.data[i]=col[0]+light*62;im.data[i+1]=col[1]+light*14;im.data[i+2]=col[2]+light*18;im.data[i+3]=a*230;}c.putImageData(im,0,0);cache.set(key,cv);if(cache.size>15)cache.delete(cache.keys().next().value);return cv;}
export function paintCloudAtmosphere(c,time,input={}){const f=Object.fromEntries(Object.entries(livingSkyDefaults).map(([k,v])=>[k,input[k]??v])),q=time*8,n=Math.floor(q),blend=q-n,alpha=c.globalAlpha;c.save();for(let layer=0;layer<Math.max(1,Math.min(4,Math.round(f.skyLayers)));layer++){c.globalAlpha=alpha*f.skyOpacity*(1-blend)/(1+layer*.35);c.drawImage(fieldFrame(n,layer,f),0,-35+layer*12,960,600);c.globalAlpha=alpha*f.skyOpacity*blend/(1+layer*.35);c.drawImage(fieldFrame(n+1,layer,f),0,-35+layer*12,960,600);}c.restore();return {frame:n,blend};}
export function paintLivingSky(c,time,images={},input={}){const f=Object.fromEntries(Object.entries(livingSkyDefaults).map(([k,v])=>[k,input[k]??v]));c.save();c.fillStyle=f.skyColor;c.fillRect(0,0,960,540);if(images.salvageSky){c.globalAlpha=.16;c.filter='grayscale(1) contrast(1.6)';const im=images.salvageSky,w=im.naturalWidth||im.width,h=im.naturalHeight||im.height,k=Math.max(1200/w,650/h);c.drawImage(im,-120-Math.sin(time*.05)*40,-60,w*k,h*k);c.filter='none';c.globalAlpha=1;}const q=time*8,n=Math.floor(q),blend=q-n;for(let layer=0;layer<Math.max(1,Math.min(4,Math.round(f.skyLayers)));layer++){c.globalAlpha=f.skyOpacity*(1-blend)/(1+layer*.35);c.drawImage(fieldFrame(n,layer,f),0,-35+layer*12,960,600);c.globalAlpha=f.skyOpacity*blend/(1+layer*.35);c.drawImage(fieldFrame(n+1,layer,f),0,-35+layer*12,960,600);}c.globalAlpha=1;const g=c.createLinearGradient(0,0,0,540);g.addColorStop(0,'#09010c66');g.addColorStop(.5,'#3d001200');g.addColorStop(1,'#1a0a1477');c.fillStyle=g;c.fillRect(0,0,960,540);c.restore();return {frame:n,blend};}
